function encodeFileToHdDataUrl(file: File, maxDim = 1150, quality = 0.84): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(new Error('Failed to read image file'));
    reader.onload = () => {
      const rawUrl = String(reader.result || '');
      const img = new window.Image();
      img.onerror = () => resolve(rawUrl);
      img.onload = () => {
        let w = img.naturalWidth || img.width || 800;
        let h = img.naturalHeight || img.height || 1000;
        if (w > maxDim || h > maxDim) {
          const ratio = Math.min(maxDim / w, maxDim / h);
          w = Math.round(w * ratio);
          h = Math.round(h * ratio);
        }
        const canvas = document.createElement('canvas');
        canvas.width = w;
        canvas.height = h;
        const ctx = canvas.getContext('2d');
        if (!ctx) {
          resolve(rawUrl);
          return;
        }
        ctx.fillStyle = '#FFFFFF';
        ctx.fillRect(0, 0, w, h);
        ctx.drawImage(img, 0, 0, w, h);
        resolve(canvas.toDataURL('image/jpeg', quality));
      };
      img.src = rawUrl;
    };
    reader.readAsDataURL(file);
  });
}

function normalizeRenderableImageUrl(rawUrl: string): string {
  if (!rawUrl) return '';
  const s = String(rawUrl).trim();
  if (s.startsWith('data:image/')) return s;
  // Convert Google Drive /file/d/ID/view or ?id=ID into direct renderable thumbnail URL
  const driveFileMatch = s.match(/\/file\/d\/([a-zA-Z0-9_-]+)/) || s.match(/[?&]id=([a-zA-Z0-9_-]+)/);
  if (driveFileMatch && driveFileMatch[1]) {
    return `https://drive.google.com/thumbnail?id=${driveFileMatch[1]}&sz=w1200`;
  }
  if (s.startsWith('http://') || s.startsWith('https://')) return s;
  return '';
}

